// Monta as janelas e as URLs da Instagram Graph API, no fuso do perfil.
// Sem URLSearchParams e sem Intl: o sandbox do task runner do n8n nao expoe
// nenhum dos dois. A data sai do $now (Luxon).
const p  = $input.first().json;
const tz = p.timezone || 'America/Sao_Paulo';

const base = $now.setZone(tz).startOf('day');       // hoje 00:00 no fuso
const dia  = base.minus({ days: 1 }).toFormat('yyyy-MM-dd');   // D-1

// BORDAS COMO UNIX TIMESTAMP DE MEIA-NOITE NO FUSO DO PERFIL.
//
// Passar data como string faz a Meta cravar a janela na meia-noite UTC.
// Medido na API: since=2026-09-01 devolveu a janela
//   2026-09-01 00:00 UTC -> 2026-09-02 00:00 UTC
// que em Sao Paulo e 31/08 21:00 -> 01/09 21:00. Tres horas deslocado, e as
// tres primeiras horas do dia caem no bucket seguinte.
//
// Com timestamp a janela e o dia de Sao Paulo de verdade, e casa com o dia
// de ads_insight_dia — que e o que torna o custo por seguidor um join direto.
const ts = (dt) => String(Math.floor(dt.toSeconds()));

const d1_de  = ts(base.minus({ days: 1 }));   // D-1 00:00 no fuso
const d1_ate = ts(base);                      // D   00:00 no fuso

const jIns  = Math.min(Number(p.janela_insights || 30), 30);  // teto da API
const jPost = Number(p.janela_posts || 90);

const G = 'https://graph.facebook.com/v23.0/';
const q = (o) => Object.keys(o)
  .map(k => encodeURIComponent(k) + '=' + encodeURIComponent(o[k]))
  .join('&');

// 1. O SNAPSHOT. followers_count e o valor do INSTANTE — a Meta nao guarda
//    historico. Esta e a unica chamada cuja falha e irrecuperavel.
const url_perfil = G + p.perfil_id + '?' + q({
  fields: 'id,username,name,followers_count,follows_count,media_count'
});

// 2. Os tres agregados. `views` substituiu `impressions` em 03/2025 e as tres
//    SO existem como metric_type=total_value — perderam a serie diaria. Logo:
//    uma chamada por dia, e nada de historico para tras.
const url_totais = G + p.perfil_id + '/insights?' + q({
  metric: 'views,profile_views,website_clicks',
  metric_type: 'total_value', period: 'day',
  since: d1_de, until: d1_ate
});

// 3. Ganhos e perdas. Breakdown por follow_type devolve FOLLOWER e
//    NON_FOLLOWER. Confirmado na API.
const url_follows = G + p.perfil_id + '/insights?' + q({
  metric: 'follows_and_unfollows', metric_type: 'total_value',
  breakdown: 'follow_type', period: 'day',
  since: d1_de, until: d1_ate
});

// 4. Alcance: a UNICA das quatro que mantem serie diaria, entao vem em bloco
//    de 30 dias. O bucket dela e do Pacifico, nao do fuso do perfil — o
//    Code node rotula com isso em mente.
const url_alcance = G + p.perfil_id + '/insights?' + q({
  metric: 'reach', period: 'day',
  since: ts(base.minus({ days: jIns })), until: ts(base)
});

// 5. Posts. like_count e comments_count vem no proprio no de midia — nao
//    precisa de uma chamada de insights por post.
const url_midias = G + p.perfil_id + '/media?' + q({
  fields: 'id,caption,media_type,media_product_type,permalink,thumbnail_url,'
        + 'timestamp,like_count,comments_count',
  since: ts(base.minus({ days: jPost })), limit: '50'
});

return [{ json: { ...p, dia, d1_de, d1_ate,
                  url_perfil, url_totais, url_follows, url_alcance,
                  url_midias } }];

