insert into ads_ingestao_log (fluxo, conta_id, janela_de, janela_ate, status)
values ('4.04', $1, $2::date, $3::date, 'rodando')
returning id;

parameters.jsCode:
const j = $('Janela').first().json;
const porDia = {};

const linha = (d) => (porDia[d] = porDia[d] || {
  dia: d, perfil_id: String(j.perfil_id),
  ganhos: null, perdidos: null,
  alcance: null, visualizacoes: null, visitas_perfil: null, cliques_site: null,
});

const PACIFICO = 'America/Los_Angeles';
const diaDoBucket = (endTime) =>
  DateTime.fromISO(endTime, { zone: 'utc' })
          .setZone(PACIFICO)
          .minus({ days: 1 })
          .toFormat('yyyy-MM-dd');

const COL_TOTAL = { views: 'visualizacoes', profile_views: 'visitas_perfil',
                    website_clicks: 'cliques_site' };
const COL_SERIE = { reach: 'alcance' };

const allItems = [];
for (const src of ['Totais do Dia', 'Follows e Unfollows', 'Alcance 30d']) {
  try { allItems.push(...$(src).all()); } catch(e) {}
}
for (const item of allItems) {
  const body = item.json || {};
  if (body.error) continue;
  for (const m of (body.data || [])) {
    const nome = m.name;
    const tv   = m.total_value;

    if (tv && tv.value !== undefined && tv.value !== null && COL_TOTAL[nome]) {
      linha(j.dia)[COL_TOTAL[nome]] = Number(tv.value);
    }

    if (tv && tv.breakdowns) {
      const L = linha(j.dia);
      for (const b of tv.breakdowns) {
        for (const r of (b.results || [])) {
          const k = String((r.dimension_values || [])[0] || '').toUpperCase();
          if (k === 'NON_FOLLOWER' || k.indexOf('UNFOLLOW') >= 0) {
            L.perdidos = Number(r.value ?? 0);
          } else if (k === 'FOLLOWER' || k === 'FOLLOW') {
            L.ganhos = Number(r.value ?? 0);
          }
        }
      }
    }

    for (const v of (m.values || [])) {
      if (!v.end_time || !COL_SERIE[nome]) continue;
      linha(diaDoBucket(v.end_time))[COL_SERIE[nome]] = Number(v.value ?? 0);
    }
  }
}

const rows = Object.keys(porDia).sort().map(k => porDia[k]);
return [{ json: {
  perfil_id: String(j.perfil_id), dia: j.dia,
  linhas: rows.length,
  payload: JSON.stringify(rows),
} }];

// Uma linha por post. `dia` = D-1, o mesmo do fato de perfil, para a taxa
// de engajamento ter denominador do mesmo dia.
//
// ATENCAO: curtidas e comentarios sao ACUMULADOS do post, nao do dia. O
// snapshot diario e proposital — vw_ig_post_delta tira a diferenca quando
// alguem quiser "curtidas do dia".
const j = $('Janela').first().json;
const rows = [];
let paginas = 0;

for (const item of $input.all()) {
  const body = item.json || {};
  if (body.error) continue;
  paginas++;
  for (const m of (body.data || [])) {
    rows.push({
      dia: j.dia,
      post_id: String(m.id),
      perfil_id: String(j.perfil_id),
      tipo: m.media_type || null,
      produto: m.media_product_type || null,
      caption: m.caption ? String(m.caption).slice(0, 2200) : null,
      permalink: m.permalink || null,
      thumbnail_url: m.thumbnail_url || null,
      publicado_em: m.timestamp || null,
      curtidas: m.like_count === undefined ? null : Number(m.like_count),
      comentarios: m.comments_count === undefined ? null : Number(m.comments_count),
    });
  }
}

return [{ json: {
  perfil_id: String(j.perfil_id), dia: j.dia,
  paginas, posts: rows.length,
  payload: JSON.stringify(rows),
} }];

